1	import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
2	import prisma from "../lib/prisma.js";
3	import jwt from "jsonwebtoken";
4	
5	const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
6	
7	// Authorization 헤더에서 토큰 추출
8	function extractToken(request: FastifyRequest): string | null {
9	  const auth = request.headers.authorization;
10	  if (!auth) return null;
11	  const match = auth.match(/^Token\s+(.+)$/i);
12	  return match ? match[1] : null;
13	}
14	
15	// 토큰 디코딩
16	function verifyToken(token: string): { id: string; username: string; email: string } {
17	  return jwt.verify(token, JWT_SECRET) as any;
18	}
19	
20	// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거
21	function slugify(title: string): string {
22	  return title
23	    .toLowerCase()
24	    .trim()
25	    .replace(/[^\w\s-]/g, "")
26	    .replace(/[\s_]+/g, "-")
27	    .replace(/^-+|-+$/g, "");
28	}
29	
30	// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
31	function normalizeTags(tagList: (string | null | undefined)[]): string[] {
32	  if (!tagList) return [];
33	  const tags = tagList
34	    .map((t) => {
35	      if (t === null || t === undefined || t === "") return null;
36	      return t.trim().toLowerCase();
37	    })
38	    .filter((t): t is string => t !== null && t !== "");
39	  return [...new Set(tags)];
40	}
41	
42	export async function articlesRoutes(app: FastifyInstance): Promise<void> {
43	  // POST /api/articles - 아티클 생성
44	  app.post("/api/articles", async (request, reply) => {
45	    const token = extractToken(request);
46	    if (!token) {
47	      return reply.code(401).send({ errors: { token: ["is missing"] } });
48	    }
49	
50	    const { article } = (request.body as any) as { article?: any };
51	    const { title, description, body, tagList } = article || {};
52	
53	    // 필수 필드 검증
54	    if (!title || title.trim() === "") {
55	      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
56	    }
57	    if (!description || description.trim() === "") {
58	      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
59	    }
60	    if (!body || body.trim() === "") {
61	      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
62	    }
63	
64	    const decoded = verifyToken(token);
65	    const normalizedTags = normalizeTags(tagList);
66	
67	    // 태그 조회/생성 (트랜잭션)
68	    let tagRecords: { id: string; name: string }[] = [];
69	    if (normalizedTags.length > 0) {
70	      const existingTags = await prisma.tag.findMany({
71	        where: { name: { in: normalizedTags } },
72	        select: { id: true, name: true },
73	      });
74	      const existingNames = new Set((existingTags as Array<{ name: string }>).map((t) => t.name));
75	      const newTags = normalizedTags.filter((n) => !existingNames.has(n));
76	
77	      if (newTags.length > 0) {
78	        const opts: any = { data: newTags.map((name) => ({ name })), skipDuplicates: true };
79	        await prisma.tag.createMany(opts);
80	      }
81	      tagRecords = await prisma.tag.findMany({
82	        where: { name: { in: normalizedTags } },
83	        select: { id: true, name: true },
84	      });
85	    }
86	
87	    const slug = slugify(title);
88	    const created = await prisma.article.create({
89	      data: {
90	        title: title.trim(),
91	        description: description.trim(),
92	        body: body.trim(),
93	        slug,
94	        authorId: decoded.id,
95	        tags: {
96	          connect: tagRecords.map((t) => ({ id: t.id })),
97	        },
98	      },
99	      include: {
100	        author: {
101	          select: { id: true, username: true, bio: true, image: true },
102	        },
103	        tags: { select: { name: true } },
104	      },
105	    });
106	
107	    return reply.code(201).send({
108	      article: {
109	        title: created.title,
110	        slug: created.slug,
111	        description: created.description,
112	        body: created.body,
113	        tagList: (created.tags as Array<{ name: string }>).map((t) => t.name),
114	        createdAt: created.createdAt,
115	        updatedAt: created.updatedAt,
116	        favorited: false,
117	        favoritesCount: 0,
118	        author: {
119	          username: created.author.username,
120	          bio: created.author.bio ?? null,
121	          image: created.author.image ?? null,
122	        },
123	      },
124	    });
125	  });
126	
127	  // GET /api/articles - 아티클 목록 조회 (필터: author, tag, favorited)
128	  app.get("/api/articles", async (request: any, reply) => {
129	    const token = extractToken(request);
130	    const authorFilter = request.query?.author as string | undefined;
131	    const tagFilter = request.query?.tag as string | undefined;
132	    const favoritedFilter = request.query?.favorited as string | undefined;
133	    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);
134	    const offset = parseInt(request.query?.offset as string ?? "0", 10);
135	
136	    // favorited 필터 — 먼저 존재하여 articleIds 확보
137	    let favArticleIds: string[] = [];
138	    if (favoritedFilter) {
139	      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });
140	      if (!favUser) {
141	        return reply.send({ articles: [], articlesCount: 0 });
142	      }
143	      favArticleIds = await prisma.$queryRaw<string[]>`
144	        SELECT article_id FROM "Favorite" WHERE user_id = ${favUser.id}
145	      `;
146	    }
147	
148	    // author 필터
149	    let authorId: string | undefined;
150	    if (authorFilter) {
151	      const author = await prisma.user.findUnique({ where: { username: authorFilter } });
152	      if (!author) {
153	        return reply.send({ articles: [], articlesCount: 0 });
154	      }
155	      authorId = author.id;
156	    }
157	
158	    // tag 필터
159	    let tagId: string | undefined;
160	    if (tagFilter) {
161	      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });
162	      if (!tag) {
163	        return reply.send({ articles: [], articlesCount: 0 });
164	      }
165	      tagId = tag.id;
166	    }
167	
168	    // where 조건 구성
169	    const where: any = {};
170	    if (authorId) where.authorId = authorId;
171	    if (favArticleIds.length > 0) {
172	      where.id = { in: favArticleIds };
173	    }
174	    if (tagId) {
175	      where.tags = { some: { id: tagId } };
176	    }
177	
178	    // 전체 카운트
179	    const total = await prisma.article.count({ where });
180	
181	    const articles = await prisma.article.findMany({
182	      where,
183	      include: {
184	        author: {
185	          select: { id: true, username: true, bio: true, image: true },
186	        },
187	        tags: { select: { name: true } },
188	      },
189	      orderBy: { createdAt: "desc" },
190	      take: limit,
191	      skip: offset,
192	    });
193	
194	    // favorited 상태 확인 (토큰이 있는 경우)
195	    let currentUserId: string | null = null;
196	    if (token) {
197	      try {
198	        currentUserId = verifyToken(token).id;
199	      } catch {
200	        // invalid token, treat as no auth
201	      }
202	    }
203	
204	    // favorited 상태 batch 체크
205	    const articleIds = articles.map((a: any) => a.id);
206	    let favoritedMap: Record<string, boolean> = {};
207	    let favCountMap: Record<string, number> = {};
